1	package retention
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"sync"
13		"syscall"
14	)
15	
16	// 状态文件与锁文件的固定名称，位于调用者选择的本地目录内。
17	const (
18		stateFileName = "retention-state.json"
19		lockFileName  = ".retention.lock"
20	)
21	
22	// Store 是一个本地保管库，对应调用者选择的一个本地保存位置。
23	//
24	// 同一个目录可以被本机上的多个程序（进程）同时打开：
25	// 每次办理都会取得跨进程的排他文件锁，并从磁盘重新读取状态，
26	// 因此两个程序对同一档案的冻结、销毁一定有明确的先后顺序。
27	type Store struct {
28		dir string
29	
30		// opMu 串行化当前 Store 实例内的办理；跨进程互斥由文件锁保证。
31		opMu sync.RWMutex
32	}
33	
34	// Open 打开（或创建）一个本地保存位置。
35	// 目录不存在时会创建；状态文件不存在时按空库打开，可以正常登记。
36	// 状态文件已存在但内容损坏（空文件、只有空白、内容为 null、合法对象后面
37	// 还拼接了其他内容等），或其中保存的记录不满足业务不变量（例如已解除冻结
38	// 缺少解除原因或解除日期、解除日期早于冻结日期、已销毁档案与已关闭清册
39	// 对应不上、已关闭清册条目保存的类别、起算日或截止日（须为销毁时最终
40	// 生效的期限）与档案登记内容不一致、修订记录衔接不上、成功修订编号在保存
41	// 历史中不唯一或与已关闭清册的申请编号相同）时返回 ErrCorruptState，
42	// 不会返回可继续办理的保管库，已有记录保持原样，不会被清空、修补或覆盖。
43	func Open(dir string) (*Store, error) {
44		if dir == "" {
45			return nil, errors.New("retention: 保存位置不能为空")
46		}
47		if err := os.MkdirAll(dir, 0o755); err != nil {
48			return nil, fmt.Errorf("retention: 无法创建保存位置: %w", err)
49		}
50		s := &Store{dir: dir}
51		// 提前读一次，让损坏的状态文件在打开时就暴露，而不是等到第一次办理。
52		if _, err := s.load(); err != nil {
53			return nil, err
54		}
55		return s, nil
56	}
57	
58	// Close 释放保管库。当前实现没有跨操作持有的资源，保留它以稳定公开入口形态。
59	func (s *Store) Close() error { return nil }
60	
61	func (s *Store) statePath() string { return filepath.Join(s.dir, stateFileName) }
62	func (s *Store) lockPath() string  { return filepath.Join(s.dir, lockFileName) }
63	
64	// lock 取得跨进程排他锁，返回解锁函数。
65	// 每次办理各自加锁、解锁，这样同一位置也允许同进程或跨进程的多个 Store 并存。
66	func (s *Store) lock() (func(), error) {
67		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
68		if err != nil {
69			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
70		}
71		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
72			f.Close()
73			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
74		}
75		return func() {
76			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
77			_ = f.Close()
78		}, nil
79	}
80	
81	// rlock 取得跨进程共享锁，用于只读核对。
82	func (s *Store) rlock() (func(), error) {
83		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
84		if err != nil {
85			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
86		}
87		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
88			f.Close()
89			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
90		}
91		return func() {
92			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
93			_ = f.Close()
94		}, nil
95	}
96	
97	// load 从磁盘读取最新状态。文件不存在时返回一份空状态（尚未建立记录）。
98	//
99	// 文件已经存在时，必须完整包含且只包含一个 JSON 对象（前后允许空白）：
100	// 零字节或只有空白的文件、内容为 null 的文件、合法对象后面还拼接了
101	// 第二个 JSON 值或无法解析的文字，都判为损坏并返回 ErrCorruptState，
102	// 绝不只使用前一段内容，也不会改动原文件。
103	//
104	// JSON 能解析不代表记录合法：任何已解除冻结都必须同时带有非空白的
105	// 解除原因和有效的解除日期，且解除日期不早于冻结日期——与解除功能
106	// 办理时的要求一致。缺少任一信息或日期顺序不成立时，整份保管库同样
107	// 判为损坏并返回 ErrCorruptState，错误信息指明涉及的档案与冻结编号。
108	//
109	// 已销毁档案与已关闭清册也必须相互对应：每份已销毁档案记下的申请编号
110	// 必须能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案
111	// 也必须存在、标成已销毁并指回这份清册。已销毁档案找不到清册、同一档案
112	// 出现在多份清册、归属指向别的申请，或未销毁档案仍挂有清册申请编号，
113	// 都说明记录已无法说明档案由哪次申请销毁，整份保管库判为损坏并返回
114	// ErrCorruptState，错误信息指明涉及的档案编号与相关申请编号。
115	//
116	// 仅归属对应还不够：已关闭清册中的每条档案条目是销毁成功那一刻登记内容
117	// 的快照，其类别、起算日、截止日必须与对应档案当前保存的登记内容逐项
118	// 一致。档案销毁后期限不能再修订，编号、类别与起算日也从不改动，所以
119	// 合法记录中两处必然相同；截止日必须是销毁时最终生效的期限（最后一次
120	// 成功修订的新截止日，没有修订时为最初登记的截止日），即使修订历史衔接
121	// 完整、清册归属正确，保存成最初登记的截止日也属损坏。任一条目在类别、
122	// 起算日、截止日任一项上不一致，两处记录就互相矛盾，整份保管库判为
123	// 损坏并返回 ErrCorruptState，错误信息指明清册申请编号、档案编号与
124	// 不一致的项目；绝不挑选其中一处作为可信记录，也不通过覆盖清册、修改
125	// 档案或删除记录消除差异。一份清册收录多份档案时，一份条目矛盾就使
126	// 整份保管库无法读取，不会返回其余条目的正常结果。
127	//
128	// 最初截止日、修订记录与当前截止日也必须连续对应：第一条修订的原截止日
129	// 等于最初截止日，后续每条的原截止日等于上一条的新截止日，最后一条的
130	// 新截止日等于当前截止日；没有修订时最初截止日与当前截止日相同。修订
131	// 日期仅用于记录，历史不按该日期重新排列。出现断开的修订关系、当前截止日
132	// 与末次修订不符、修订列表中存在空记录，或已有修订却缺少最初截止日时，
133	// 两个日期中任何一个都不能当作可靠依据，整份保管库判为损坏并返回
134	// ErrCorruptState，错误信息指明涉及的档案编号，能对应到具体修订时
135	// 同时指明修订编号。
136	//
137	// 每个成功修订编号在整个保管库内只能对应一条保存的修订记录，且不能与
138	// 已关闭清册的申请编号相同——与办理时“修订编号全库唯一、与销毁申请编号
139	// 互不占用”的要求一致。同一档案历史中重复出现同一编号、不同档案各自保存
140	// 同号修订（即使两条记录内容完全相同），或某条修订的编号与一份已关闭
141	// 清册的申请编号相同，都无法仅凭编号唯一确定应取回哪条修订，整份保管库
142	// 判为损坏并返回 ErrCorruptState；绝不合并记录或挑选其中一条继续使用。
143	// 错误信息指明冲突编号：同档案重复时指出该档案，跨档案重复时指出两份
144	// 档案，与清册冲突时指出修订所属档案与清册申请编号。
145	func (s *Store) load() (*storeData, error) {
146		raw, err := os.ReadFile(s.statePath())
147		if err != nil {
148			if errors.Is(err, os.ErrNotExist) {
149				return newStoreData(), nil
150			}
151			return nil, fmt.Errorf("retention: 无法读取状态文件: %w", err)
152		}
153		trimmed := bytes.TrimSpace(raw)
154		if len(trimmed) == 0 {
155			return nil, fmt.Errorf("retention: 状态文件为空或只有空白: %w", ErrCorruptState)
156		}
157		// json.Unmarshal 对 null 不报错且保持目标不变，必须单独拒绝。
158		if string(trimmed) == "null" {
159			return nil, fmt.Errorf("retention: 状态文件内容为 null，不是有效的保管库记录: %w", ErrCorruptState)
160		}
161		data := newStoreData()
162		// json.Unmarshal 要求整个输入恰好是一个 JSON 值：
163		// 合法对象后面再拼接任何内容都会在这里报错。
164		if err := json.Unmarshal(raw, data); err != nil {
165			return nil, fmt.Errorf("retention: 状态文件内容无法解析: %v: %w", err, ErrCorruptState)
166		}
167		if data.Archives == nil {
168			data.Archives = map[string]*archiveRecord{}
169		}
170		if data.Manifests == nil {
171			data.Manifests = map[string]*manifestRecord{}
172		}
173		// 语义校验先于任何兼容处理：已解除冻结必须与既有解除功能遵守同一要求——
174		// 解除原因与解除日期齐备，且解除日期不早于冻结日期。
175		// 只有“已解除”标记而缺少任一信息，或解除日期早于冻结日期的记录
176		// 一律判为损坏（即使所属档案已销毁）；绝不据此继续办理或修补记录。
177		if err := validateFreezeReleaseRecords(data); err != nil {
178			return nil, err
179		}
180		// 已销毁档案与已关闭清册必须相互对应，否则无法说明档案由哪次申请销毁。
181		// 关系损坏时绝不挑选其中一份记录继续使用，也不补清册或改销毁标记。
182		if err := validateManifestConsistency(data); err != nil {
183			return nil, err
184		}
185		// 兼容引入修订功能之前保存的保管库：没有修订记录也没有最初截止日时，
186		// 登记截止日就是最初截止日。已有修订却缺少最初截止日的记录不能据此
187		// 冒充，由 validateRevisionContinuity 按损坏拒绝。
188		for _, ar := range data.Archives {
189			if ar != nil && len(ar.Revisions) == 0 && ar.InitialEnd.IsZero() {
190				ar.InitialEnd = ar.End
191			}
192		}
193		// 已关闭清册中的每条档案条目是销毁成功那一刻的登记内容快照，
194		// 其类别、起算日与截止日必须与对应档案保存的登记内容逐项一致，
195		// 截止日必须是该档案销毁时最终生效的期限，不能拿最初登记的截止日顶替。
196		if err := validateManifestSnapshots(data); err != nil {
197			return nil, err
198		}
199		// 最初截止日、修订记录与当前截止日必须连续衔接，否则当前期限与
200		// 历史期限相互矛盾，任何一个日期都不能当作核对依据。
201		if err := validateRevisionContinuity(data); err != nil {
202			return nil, err
203		}
204		// 成功修订编号在整个保管库内只能对应一条保存的修订记录，且不能与
205		// 已关闭清册的申请编号相同——与办理时全库唯一、编号互不占用的要求一致。
206		if err := validateRevisionIDs(data); err != nil {
207			return nil, err
208		}
209		return data, nil
210	}
211	
212	// validateFreezeReleaseRecords 检查库内全部已解除冻结记录是否完整合法。
213	//
214	// 正常解除保存的记录必然同时带有非空白的解除原因和有效的解除日期，
215	// 且解除日期不早于冻结日期。缺少解除原因、解除日期缺失或为 null、
216	// 解除日期早于冻结日期，都说明保存内容已损坏，返回可由 ErrCorruptState
217	// 识别的错误，并在信息中给出涉及的档案编号与冻结编号，便于定位记录。
218	// 校验覆盖整个保管库的全部已解除冻结，与本次办理名单无关：
219	// 即使异常记录所属档案已经销毁，也不能把不完整的解除信息当作正常历史。
220	// 未解除冻结没有解除日期和原因是合法状态，不在此报错。
221	func validateFreezeReleaseRecords(data *storeData) error {
222		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
223		archiveIDs := make([]string, 0, len(data.Archives))
224		for id := range data.Archives {
225			archiveIDs = append(archiveIDs, id)
226		}
227		sort.Strings(archiveIDs)
228		for _, id := range archiveIDs {
229			ar := data.Archives[id]
230			if ar == nil {
231				return fmt.Errorf("retention: 档案 %s 的登记记录缺失，状态文件已损坏: %w",
232					id, ErrCorruptState)
233			}
234			for _, fr := range ar.Freezes {
235				if fr == nil {
236					return fmt.Errorf("retention: 档案 %s 下存在缺失的冻结记录，状态文件已损坏: %w",
237						id, ErrCorruptState)
238				}
239				if !fr.Released {
240					// 未解除冻结没有解除日期与原因是合法状态。
241					continue
242				}
243				switch {
244				case strings.TrimSpace(fr.ReleaseReason) == "":
245					return fmt.Errorf(
246						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除原因，记录已损坏: %w",
247						id, fr.ID, ErrCorruptState)
248				case fr.ReleasedOn == nil:
249					return fmt.Errorf(
250						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除日期，记录已损坏: %w",
251						id, fr.ID, ErrCorruptState)
252				case fr.ReleasedOn.IsZero():
253					return fmt.Errorf(
254						"retention: 档案 %s 的冻结 %s 的解除日期无效，记录已损坏: %w",
255						id, fr.ID, ErrCorruptState)
256				case fr.ReleasedOn.Before(fr.FrozenOn):
257					return fmt.Errorf(
258						"retention: 档案 %s 的冻结 %s 的解除日期 %s 早于冻结日期 %s，记录已损坏: %w",
259						id, fr.ID, fr.ReleasedOn, fr.FrozenOn, ErrCorruptState)
260				}
261			}
262		}
263		return nil
264	}
