372	// validateManifestSnapshots 检查每份已关闭清册中的档案条目是否与对应档案
373	// 当前保存的登记内容逐项一致。
374	//
375	// 清册在销毁成功那一刻关闭，条目是关闭瞬间登记内容的快照：档案销毁后
376	// 不能再修订期限，编号、类别与起算日也从不改动，因此合法记录中清册条目
377	// 的类别、起算日与截止日必然与对应档案保存的值相同——其中截止日必须是
378	// 该档案销毁时最终生效的期限（等于最后一次成功修订的新截止日；没有修订
379	// 时等于最初登记的截止日），不能拿最初登记的截止日顶替。延长、缩短或
380	// 改回曾经使用过的日期都沿用这一规则，不按修订记录中的办理日期重新选择。
381	//
382	// 任一条目在类别、起算日、截止日任一项上与档案不一致，两处记录就互相
383	// 矛盾，任何一处都不能当作可信依据：返回可由 ErrCorruptState 识别的错误，
384	// 绝不挑选其中一份继续使用，也不通过覆盖清册、修改档案或删除记录消除差异。
385	// 错误信息给出清册申请编号、档案编号与不一致的项目（类别、起算日、
386	// 保管截止日，并附上两处各自保存的值）。校验覆盖整个保管库的全部清册
387	// 与全部条目，与本次办理名单或查询目标无关：一份清册收录多份档案时，
388	// 只要有一份条目矛盾，整份保管库都判为损坏，不会返回其余条目的正常结果。
389	func validateManifestSnapshots(data *storeData) error {
390		// map 遍历顺序不稳定，按申请编号、条目顺序检查，保证错误信息稳定。
391		appIDs := make([]string, 0, len(data.Manifests))
392		for appID := range data.Manifests {
393			appIDs = append(appIDs, appID)
394		}
395		sort.Strings(appIDs)
396		for _, appID := range appIDs {
397			rec := data.Manifests[appID]
398			if rec == nil {
399				// 缺失的清册记录已由 validateManifestConsistency 报告。
400				continue
401			}
402			for _, e := range rec.Entries {
403				ar, ok := data.Archives[e.ID]
404				if !ok || ar == nil {
405					// 清册收录不存在档案等归属问题已由 validateManifestConsistency 报告。
406					continue
407				}
408				items := make([]string, 0, 3)
409				if e.Category != ar.Category {
410					items = append(items, fmt.Sprintf("类别（清册 %q，档案 %q）", e.Category, ar.Category))
411				}
412				if !e.Start.Equal(ar.Start) {
413					items = append(items, fmt.Sprintf("起算日（清册 %s，档案 %s）", e.Start, ar.Start))
414				}
415				if !e.End.Equal(ar.End) {
416					items = append(items, fmt.Sprintf("保管截止日（清册 %s，档案 %s）", e.End, ar.End))
417				}
418				if len(items) > 0 {
419					return fmt.Errorf(
420						"retention: 清册 %s 中档案 %s 的条目与档案登记内容不一致：%s，记录已损坏: %w",
421						appID, e.ID, strings.Join(items, "、"), ErrCorruptState)
422				}
423			}
424		}
425		return nil
426	}
427	
428	// validateRevisionContinuity 检查每份档案的最初截止日、修订记录与当前截止日
429	// 是否连续对应。
430	//
431	// 正常办理保存的记录必然满足：第一条修订的原截止日等于最初截止日，后续每条
432	// 的原截止日等于上一条的新截止日，最后一条的新截止日等于当前截止日；没有
433	// 修订时最初截止日与当前截止日相同。修订日期仅用于记录办理时间，不决定生效
434	// 先后，因此历史不按修订日期重新排列，只按保存顺序核对衔接；期限被延长、
435	// 缩短或改回早先用过的日期，只要衔接完整都是合法记录。
436	//
437	// 出现断开的修订关系、当前截止日与末次修订的新截止日不符、修订列表中存在
438	// 空记录，或已有修订却缺少最初截止日（不能把当前期限冒充最初期限）时，
439	// 保存内容已无法说明期限如何演变，返回可由 ErrCorruptState 识别的错误，
440	// 并在信息中给出涉及的档案编号；能对应到具体修订时同时给出修订编号。
441	// 校验覆盖整个保管库的全部档案（含已销毁的），与本次办理名单无关。
442	func validateRevisionContinuity(data *storeData) error {
443		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
444		archiveIDs := make([]string, 0, len(data.Archives))
445		for id := range data.Archives {
446			archiveIDs = append(archiveIDs, id)
447		}
448		sort.Strings(archiveIDs)
449		for _, id := range archiveIDs {
450			ar := data.Archives[id]
451			if ar == nil {
452				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
453				continue
454			}
455			if len(ar.Revisions) == 0 {
456				// 没有修订时最初截止日与当前截止日必须相同
457				// （旧记录缺少最初截止日的情形已在 load 中按登记截止日补齐）。
458				if !ar.InitialEnd.Equal(ar.End) {
459					return fmt.Errorf(
460						"retention: 档案 %s 没有修订记录，但最初截止日 %s 与当前截止日 %s 不一致，记录已损坏: %w",
461						id, ar.InitialEnd, ar.End, ErrCorruptState)
462				}
463				continue
464			}
465			for i, rec := range ar.Revisions {
466				if rec == nil {
467					return fmt.Errorf(
468						"retention: 档案 %s 的修订列表第 %d 条为空记录，记录已损坏: %w",
469						id, i+1, ErrCorruptState)
470				}
471			}
472			if ar.InitialEnd.IsZero() {
473				return fmt.Errorf(
474					"retention: 档案 %s 已有修订记录（首条为 %s）却缺少最初截止日，记录已损坏: %w",
475					id, ar.Revisions[0].ID, ErrCorruptState)
476			}
477			// 按保存顺序逐条核对衔接：每条的原截止日必须等于此前生效的截止日。
478			expected := ar.InitialEnd
479			for _, rec := range ar.Revisions {
480				if !rec.OldEnd.Equal(expected) {
481					return fmt.Errorf(
482						"retention: 档案 %s 的修订 %s 的原截止日 %s 与此前生效的截止日 %s 不衔接，记录已损坏: %w",
483						id, rec.ID, rec.OldEnd, expected, ErrCorruptState)
484				}
485				expected = rec.NewEnd
486			}
487			if !ar.End.Equal(expected) {
488				return fmt.Errorf(
489					"retention: 档案 %s 的当前截止日 %s 与末次修订 %s 的新截止日 %s 不符，记录已损坏: %w",
490					id, ar.End, ar.Revisions[len(ar.Revisions)-1].ID, expected, ErrCorruptState)
491			}
492		}
493		return nil
494	}
495	
496	// validateRevisionIDs 检查成功修订编号在整个保管库内的唯一性，以及与已关闭
497	// 清册申请编号的互不占用。
498	//
499	// 正常办理保存的记录必然满足：每个修订编号在全部档案的修订历史中只出现
500	// 一次，且没有任何编号同时被用作成功销毁申请的编号。同一档案历史中重复
501	// 使用同一编号、不同档案各自保存同号修订（即使两条记录的日期、原因等
502	// 内容完全相同），或修订编号与一份已关闭清册的申请编号相同，都会使
503	// “按编号重试取回唯一一条修订”无法成立，返回可由 ErrCorruptState 识别
504	// 的错误：绝不合并重复记录，也不挑选其中一条继续使用。
505	//
506	// 错误信息给出冲突的修订编号与涉及的档案编号；跨档案重复时同时给出两份
507	// 档案，与清册冲突时给出清册的申请编号。校验覆盖整个保管库的全部档案
508	// （含已销毁的），与本次办理名单或查询目标无关。修订编号为空白同样不能
509	// 作为成功记录存在，一并按损坏处理。
510	func validateRevisionIDs(data *storeData) error {
511		owners := make(map[string]string)
512		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
513		archiveIDs := make([]string, 0, len(data.Archives))
514		for id := range data.Archives {
515			archiveIDs = append(archiveIDs, id)
516		}
517		sort.Strings(archiveIDs)
518		for _, id := range archiveIDs {
519			ar := data.Archives[id]
520			if ar == nil {
521				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
522				continue
523			}
524			for _, rec := range ar.Revisions {
525				if rec == nil {
526					// 空记录已由 validateRevisionContinuity 报告。
527					continue
528				}
529				if strings.TrimSpace(rec.ID) == "" {
530					return fmt.Errorf(
531						"retention: 档案 %s 的修订历史中存在没有编号的修订记录，记录已损坏: %w",
532						id, ErrCorruptState)
533				}
534				if owner, ok := owners[rec.ID]; ok {
535					if owner == id {
536						return fmt.Errorf(
537							"retention: 修订编号 %s 在档案 %s 的历史中出现多条记录，保存记录已损坏: %w",
538							rec.ID, id, ErrCorruptState)
539					}
540					return fmt.Errorf(
541						"retention: 修订编号 %s 同时保存在档案 %s 与档案 %s 的修订历史中，保存记录已损坏: %w",
542						rec.ID, owner, id, ErrCorruptState)
543				}
544				owners[rec.ID] = id
545			}
546		}
547		// 修订编号与销毁申请编号互不占用：任何已关闭清册的申请编号都不能
548		// 同时是一条已保存修订的编号。申请编号按排序遍历，错误信息稳定。
549		appIDs := make([]string, 0, len(data.Manifests))
550		for appID := range data.Manifests {
551			appIDs = append(appIDs, appID)
552		}
553		sort.Strings(appIDs)
554		for _, appID := range appIDs {
555			if owner, ok := owners[appID]; ok {
556				return fmt.Errorf(
557					"retention: 档案 %s 的修订编号 %s 与已关闭清册的申请编号 %s 相同，保存记录已损坏: %w",
558					owner, appID, appID, ErrCorruptState)
559			}
560		}
561		return nil
562	}
563	
564	// save 原子地写入状态：先写同目录临时文件并刷盘，再 rename 替换，最后刷目录。
565	// 写入过程中崩溃不会留下半截状态，旧文件保持完好。
566	func (s *Store) save(data *storeData) error {
567		buf, err := json.MarshalIndent(data, "", "  ")
568		if err != nil {
569			return fmt.Errorf("retention: 状态编码失败: %w", err)
570		}
571		tmp, err := os.CreateTemp(s.dir, ".retention-state-*.tmp")
572		if err != nil {
573			return fmt.Errorf("retention: 无法创建临时状态文件: %w", err)
574		}
575		tmpName := tmp.Name()
576		cleanup := func() { _ = os.Remove(tmpName) }
577		if _, err := tmp.Write(buf); err != nil {
578			tmp.Close()
579			cleanup()
580			return fmt.Errorf("retention: 写入状态失败: %w", err)
581		}
582		if err := tmp.Sync(); err != nil {
583			tmp.Close()
584			cleanup()
585			return fmt.Errorf("retention: 刷盘状态失败: %w", err)
586		}
587		if err := tmp.Close(); err != nil {
588			cleanup()
589			return fmt.Errorf("retention: 关闭状态文件失败: %w", err)
590		}
591		if err := os.Rename(tmpName, s.statePath()); err != nil {
592			cleanup()
593			return fmt.Errorf("retention: 替换状态文件失败: %w", err)
594		}
595		// 刷目录，确保 rename 在崩溃后仍然落盘。
596		if dir, err := os.Open(s.dir); err == nil {
597			_ = dir.Sync()
598			_ = dir.Close()
599		}
600		return nil
601	}
602	
603	// mutate 在跨进程排他锁内重读状态、办理变更，仅在全部校验通过后写回。
604	// fn 返回错误时绝不写盘，磁盘上的已有记录不受影响。
605	func (s *Store) mutate(fn func(*storeData) error) error {
606		s.opMu.Lock()
607		defer s.opMu.Unlock()
608		unlock, err := s.lock()
609		if err != nil {
610			return err
611		}
612		defer unlock()
613		data, err := s.load()
614		if err != nil {
615			return err
616		}
617		if err := fn(data); err != nil {
618			return err
619		}
620		return s.save(data)
621	}
622	
623	// view 在共享锁内重读状态并执行只读查询。
624	func (s *Store) view(fn func(*storeData) error) error {
625		s.opMu.RLock()
626		defer s.opMu.RUnlock()
627		unlock, err := s.rlock()
628		if err != nil {
629			return err
630		}
631		defer unlock()
632		data, err := s.load()
633		if err != nil {
634			return err
635		}
636		return fn(data)
637	}
638

