1	package retention
2	
3	import (
4		"strconv"
5		"strings"
6	)
7	
8	// Date 是按日历日期（年月日）比较的日期，与时区和夏令时无关。
9	//
10	// 对外的文本格式统一为 YYYY-MM-DD。零值表示无效日期，不能用于业务。
11	type Date struct {
12		year  int
13		month int
14		day   int
15	}
16	
17	// ParseDate 按 YYYY-MM-DD 解析日期。
18	// 只接受完整的四位年份、两位月份、两位日期，且日期必须真实存在。
19	func ParseDate(s string) (Date, error) {
20		if len(s) != 10 || s[4] != '-' || s[7] != '-' {
21			return Date{}, &InvalidDateError{Value: s}
22		}
23		year, err := strconv.Atoi(s[0:4])
24		if err != nil {
25			return Date{}, &InvalidDateError{Value: s}
26		}
27		month, err := strconv.Atoi(s[5:7])
28		if err != nil {
29			return Date{}, &InvalidDateError{Value: s}
30		}
31		day, err := strconv.Atoi(s[8:10])
32		if err != nil {
33			return Date{}, &InvalidDateError{Value: s}
34		}
35		if !validCalendarDate(year, month, day) {
36			return Date{}, &InvalidDateError{Value: s}
37		}
38		return Date{year, month, day}, nil
39	}
40	
41	// MustParseDate 按 YYYY-MM-DD 解析日期，失败即 panic。
42	// 只适合在测试或字面量构造中使用。
43	func MustParseDate(s string) Date {
44		d, err := ParseDate(s)
45		if err != nil {
46			panic(err)
47		}
48		return d
49	}
50	
51	// String 返回 YYYY-MM-DD 形式的文本。
52	func (d Date) String() string {
53		var b strings.Builder
54		b.Grow(10)
55		writePadded(&b, d.year, 4)
56		b.WriteByte('-')
57		writePadded(&b, d.month, 2)
58		b.WriteByte('-')
59		writePadded(&b, d.day, 2)
60		return b.String()
61	}
62	
63	// IsZero 报告日期是否为零值（未设置）。
64	func (d Date) IsZero() bool { return d.year == 0 && d.month == 0 && d.day == 0 }
65	
66	// Before 按日历日期报告 d 是否早于 other。
67	func (d Date) Before(other Date) bool {
68		if d.year != other.year {
69			return d.year < other.year
70		}
71		if d.month != other.month {
72			return d.month < other.month
73		}
74		return d.day < other.day
75	}
76	
77	// After 按日历报告 d 是否晚于 other。
78	func (d Date) After(other Date) bool { return other.Before(d) }
79	
80	// Equal 按日历报告两个日期是否相同。
81	func (d Date) Equal(other Date) bool {
82		return d.year == other.year && d.month == other.month && d.day == other.day
83	}
84	
85	// MarshalJSON 按 YYYY-MM-DD 序列化。
86	func (d Date) MarshalJSON() ([]byte, error) {
87		return []byte(`"` + d.String() + `"`), nil
88	}
89	
90	// UnmarshalJSON 按 YYYY-MM-DD 形式反序列化并校验真实日期。
91	func (d *Date) UnmarshalJSON(data []byte) error {
92		if len(data) < 2 || data[0] != '"' || data[len(data)-1] != '"' {
93			return &InvalidDateError{Value: string(data)}
94		}
95		parsed, err := ParseDate(string(data[1 : len(data)-1]))
96		if err != nil {
97			return err
98		}
99		*d = parsed
100		return nil
101	}
102	
103	func writePadded(b *strings.Builder, value, width int) {
104		s := strconv.Itoa(value)
105		for i := len(s); i < width; i++ {
106			b.WriteByte('0')
107		}
108		b.WriteString(s)
109	}
110	
111	func validCalendarDate(year, month, day int) bool {
112		// 年份允许 0001..9999；月份、日期必须真实存在，含闰年规则。
113		if year < 1 || year > 9999 || month < 1 || month > 12 || day < 1 {
114			return false
115		}
116		daysInMonth := 31
117		switch month {
118		case 4, 6, 9, 11:
119			daysInMonth = 30
120		case 2:
121			leap := year%4 == 0 && (year%100 != 0 || year%400 == 0)
122			if leap {
123				daysInMonth = 29
124			} else {
125				daysInMonth = 28
126			}
127		}
128		return day <= daysInMonth
129	}
