1	package retention
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// 已关闭清册中的档案条目是销毁成功那一刻登记内容的快照：即使清册归属正确，
10	// 条目中的类别、起算日或截止日与对应档案保存的登记内容任一项不一致时，
11	// Open 也必须按保存记录损坏失败（ErrCorruptState），错误信息指出清册申请
12	// 编号、档案编号与不一致的项目，原文件保持原样。截止日必须是销毁时最终
13	// 生效的期限：修订衔接完整但清册保存成最初登记截止日的记录同样判为损坏。
14	func TestOpenRejectsManifestSnapshotMismatch(t *testing.T) {
15		archive := func(id, category, start, end, initial string, extra string) string {
16			return `{"id":"` + id + `","category":"` + category + `","start":"` + start + `","end":"` + end +
17				`","initial_end":"` + initial + `","destroyed":true,"manifest_id":"APP-1","freezes":[]` + extra + `}`
18		}
19		entry := func(id, category, start, end string) string {
20			return `{"id":"` + id + `","category":"` + category + `","start":"` + start + `","end":"` + end + `"}`
21		}
22		manifest := func(appID, processedOn, entries string) string {
23			return `"` + appID + `":{"application_id":"` + appID + `","processed_on":"` + processedOn +
24				`","entries":[` + entries + `]}`
25		}
26		state := func(archiveJSON, appID, processedOn, entries string) string {
27			return `{"version":1,"archives":{"A-1":` + archiveJSON + `},"manifests":{` +
28				manifest(appID, processedOn, entries) + `}}`
29		}
30	
31		a1Simple := archive("A-1", "合同", "2020-01-01", "2025-01-10", "2025-01-10", "")
32		// 登记 2025-01-10，成功延长到 2025-06-30 后销毁：修订链衔接完整，
33		// 当前（销毁时最终生效）截止日为 2025-06-30。
34		a1Extended := archive("A-1", "合同", "2020-01-01", "2025-06-30", "2025-01-10",
35			`,"revisions":[{"id":"R-1","old_end":"2025-01-10","new_end":"2025-06-30","revised_on":"2025-01-09","reason":"延期"}]`)
36	
37		corrupt := map[string]struct {
38			state string
39			want  []string
40		}{
41			"类别不一致": {
42				state(a1Simple, "APP-1", "2025-01-10", entry("A-1", "凭证", "2020-01-01", "2025-01-10")),
43				[]string{"APP-1", "A-1", "类别", "合同", "凭证"},
44			},
45			"起算日不一致": {
46				state(a1Simple, "APP-1", "2025-01-10", entry("A-1", "合同", "2020-02-01", "2025-01-10")),
47				[]string{"APP-1", "A-1", "起算日", "2020-02-01", "2020-01-01"},
48			},
49			"截止日不一致": {
50				state(a1Simple, "APP-1", "2025-01-10", entry("A-1", "合同", "2020-01-01", "2024-12-31")),
51				[]string{"APP-1", "A-1", "保管截止日", "2024-12-31", "2025-01-10"},
52			},
53			"三项同时不一致": {
54				state(a1Simple, "APP-1", "2025-01-10", entry("A-1", "凭证", "2020-02-01", "2024-12-31")),
55				[]string{"APP-1", "A-1", "类别", "起算日", "保管截止日"},
56			},
57			"延长后销毁但清册保存最初登记截止日": {
58				state(a1Extended, "APP-1", "2025-06-30", entry("A-1", "合同", "2020-01-01", "2025-01-10")),
59				[]string{"APP-1", "A-1", "保管截止日", "2025-01-10", "2025-06-30"},
60			},
61			"档案侧截止日被改动而清册未变": {
62				// 清册保存的最终期限 2025-06-30 合法，但档案当前截止日被改成 2026-01-10：
63				// 不挑选任一处作为可信记录，方向与上例相反也必须拒绝。
64				state(archive("A-1", "合同", "2020-01-01", "2026-01-10", "2025-01-10",
65					`,"revisions":[{"id":"R-1","old_end":"2025-01-10","new_end":"2025-06-30","revised_on":"2025-01-09","reason":"延期"}]`),
66					"APP-1", "2025-06-30", entry("A-1", "合同", "2020-01-01", "2025-06-30")),
67				[]string{"APP-1", "A-1", "保管截止日", "2025-06-30", "2026-01-10"},
68			},
69			"多档案清册中第二份条目类别矛盾": {
70				`{"version":1,"archives":{` + `"A-1":` + a1Simple + `,"A-2":` +
71					archive("A-2", "凭证", "2020-01-01", "2025-01-10", "2025-01-10", "") +
72					`},"manifests":{` + manifest("APP-1", "2025-01-10",
73					entry("A-1", "合同", "2020-01-01", "2025-01-10")+`,`+entry("A-2", "合同", "2020-01-01", "2025-01-10")) + `}}`,
74				[]string{"APP-1", "A-2", "类别"},
75			},
76		}
77		for name, tc := range corrupt {
78			t.Run(name, func(t *testing.T) {
79				dir := t.TempDir()
80				writeStateFile(t, dir, tc.state)
81	
82				s, err := Open(dir)
83				if err == nil {
84					s.Close()
85					t.Fatal("清册条目与档案登记内容不一致时不应打开成功")
86				}
87				if !errors.Is(err, ErrCorruptState) {
88					t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
89				}
90				for _, want := range tc.want {
91					if !strings.Contains(err.Error(), want) {
92						t.Fatalf("错误信息应指出 %q，得到 %v", want, err)
93					}
94				}
95				if got := readStateFile(t, dir); got != tc.state {
96					t.Fatalf("打开失败后原文件被改动:\n%q", got)
97				}
98			})
99		}
100	
101		// 对照组：销毁时最终生效期限与清册条目一致（含修订后销毁）必须能打开。
102		t.Run("修订后最终期限与清册一致可打开", func(t *testing.T) {
103			valid := state(a1Extended, "APP-1", "2025-06-30", entry("A-1", "合同", "2020-01-01", "2025-06-30"))
104			dir := t.TempDir()
105			writeStateFile(t, dir, valid)
106			s, err := Open(dir)
107			if err != nil {
108				t.Fatalf("清册保存销毁时最终生效截止日的记录应能打开: %v", err)
109			}
110			defer s.Close()
111			h, found, err := s.History("A-1")
112			if err != nil || !found || h.Manifest == nil {
113				t.Fatalf("合法记录的历史与清册应完整可查: found=%v err=%v", found, err)
114			}
115			if !h.Manifest.Entries[0].End.Equal(MustParseDate("2025-06-30")) {
116				t.Fatalf("清册条目应保存最终生效截止日 2025-06-30: %+v", h.Manifest.Entries[0])
117			}
118		})
119	}
120	
121	// 正常销毁生成的清册必须与档案登记内容逐项一致：延长、缩短或改回早先用过的
122	// 日期后销毁，清册保存的都是销毁时最终生效的截止日；重开后历史、清册查询、
123	// 相同申请取回原清册与销毁前核对均保持原有行为。
124	func TestValidDestroyedSnapshotsKeepWorking(t *testing.T) {
125		t.Run("延长后销毁保存最终期限", func(t *testing.T) {
126			dir := t.TempDir()
127			s, err := Open(dir)
128			if err != nil {
129				t.Fatal(err)
130			}
131			reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
132			if _, err := s.Revise(ReviseInput{
133				RevisionID: "R-1", ArchiveID: "A-1",
134				OriginalEnd: MustParseDate("2025-01-10"), NewEnd: MustParseDate("2025-06-30"),
135				RevisedOn: MustParseDate("2025-01-09"), Reason: "延期",
136			}); err != nil {
137				t.Fatal(err)
138			}
139			req := DestructionRequest{
140				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-1"},
141			}
142			m, err := s.Destroy(req)
143			if err != nil {
144				t.Fatal(err)
145			}
146			if !m.Entries[0].End.Equal(MustParseDate("2025-06-30")) {
147				t.Fatalf("清册应保存销毁时最终生效截止日 2025-06-30: %+v", m.Entries[0])
148			}
149			if err := s.Close(); err != nil {
150				t.Fatal(err)
151			}
152	
153			s2, err := Open(dir)
154			if err != nil {
155				t.Fatalf("合法记录重开应成功: %v", err)
156			}
157			defer s2.Close()
158			h, found, err := s2.History("A-1")
159			if err != nil || !found || h.Manifest == nil || len(h.Revisions) != 1 {
160				t.Fatalf("重开后历史与清册应完整: found=%v err=%v %+v", found, err, h)
161			}
162			if !h.Manifest.Entries[0].End.Equal(MustParseDate("2025-06-30")) ||
163				!h.InitialEnd.Equal(MustParseDate("2025-01-10")) ||
164				!h.RetentionEnd.Equal(MustParseDate("2025-06-30")) {
165				t.Fatalf("重开后最初/最终截止日与清册快照不正确: %+v", h)
166			}
167			got, found, err := s2.GetManifest("APP-1")
168			if err != nil || !found || !got.Entries[0].End.Equal(MustParseDate("2025-06-30")) {
169				t.Fatalf("按申请编号取回的清册应保存最终期限: found=%v err=%v %+v", found, err, got)
170			}
171			// 相同申请取回原清册的幂等行为不变。
172			replay, err := s2.Destroy(req)
173			if err != nil || replay.ApplicationID != "APP-1" || !replay.Entries[0].End.Equal(MustParseDate("2025-06-30")) {
174				t.Fatalf("相同申请应取回原清册: %+v err=%v", replay, err)
175			}
176			r, err := s2.Check(CheckRequest(req))
177			if err != nil || r.Status != CheckReplayable || r.Manifest == nil {
178				t.Fatalf("相同申请核对应显示可以取回原清册: %+v err=%v", r, err)
179			}
180		})
181	
182		t.Run("缩短后销毁保存缩短后的期限", func(t *testing.T) {
183			dir := t.TempDir()
184			s, err := Open(dir)
185			if err != nil {
186				t.Fatal(err)
187			}
188			reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
189			if _, err := s.Revise(ReviseInput{
190				RevisionID: "R-1", ArchiveID: "A-1",
191				OriginalEnd: MustParseDate("2025-01-10"), NewEnd: MustParseDate("2024-06-30"),
192				RevisedOn: MustParseDate("2024-01-05"), Reason: "提前到期",
193			}); err != nil {
194				t.Fatal(err)
195			}
196			if _, err := s.Destroy(DestructionRequest{
197				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2024-06-30"), ArchiveIDs: []string{"A-1"},
198			}); err != nil {
199				t.Fatal(err)
200			}
201			if err := s.Close(); err != nil {
202				t.Fatal(err)
203			}
204			s2, err := Open(dir)
205			if err != nil {
206				t.Fatalf("缩短后销毁的合法记录重开应成功: %v", err)
207			}
208			defer s2.Close()
209			h, found, err := s2.History("A-1")
210			if err != nil || !found || !h.Manifest.Entries[0].End.Equal(MustParseDate("2024-06-30")) {
211				t.Fatalf("清册应保存缩短后生效的截止日 2024-06-30: found=%v err=%v %+v", found, err, h)
212			}
213		})
214	
215		t.Run("改回早先用过的日期后销毁仍合法", func(t *testing.T) {
216			dir := t.TempDir()
217			s, err := Open(dir)
218			if err != nil {
219				t.Fatal(err)
220			}
221			reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
222			if _, err := s.Revise(ReviseInput{
223				RevisionID: "R-1", ArchiveID: "A-1",
224				OriginalEnd: MustParseDate("2025-01-10"), NewEnd: MustParseDate("2026-01-10"),
225				RevisedOn: MustParseDate("2025-01-02"), Reason: "延期",
226			}); err != nil {
227				t.Fatal(err)
228			}
229			if _, err := s.Revise(ReviseInput{
230				RevisionID: "R-2", ArchiveID: "A-1",
231				OriginalEnd: MustParseDate("2026-01-10"), NewEnd: MustParseDate("2025-01-10"),
232				RevisedOn: MustParseDate("2025-01-03"), Reason: "改回",
233			}); err != nil {
234				t.Fatal(err)
235			}
236			if _, err := s.Destroy(DestructionRequest{
237				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
238			}); err != nil {
239				t.Fatal(err)
240			}
241			if err := s.Close(); err != nil {
242				t.Fatal(err)
243			}
244			s2, err := Open(dir)
245			if err != nil {
246				t.Fatalf("改回日期后销毁的合法记录重开应成功: %v", err)
247			}
248			defer s2.Close()
249			h, found, err := s2.History("A-1")
250			if err != nil || !found {
251				t.Fatalf("历史查询失败: found=%v err=%v", found, err)
252			}
253			if len(h.Revisions) != 2 ||
254				!h.Manifest.Entries[0].End.Equal(MustParseDate("2025-01-10")) ||
255				!h.RetentionEnd.Equal(MustParseDate("2025-01-10")) {
256				t.Fatalf("最终生效期限为改回后的 2025-01-10，清册应照此保存: %+v", h)
257			}
258		})
259	}
260	
261	// 保管库打开后保存内容才出现清册条目与档案登记内容不一致：下一次使用有效输入
262	// 的查询、销毁前核对与各项办理都必须返回 ErrCorruptState——即使操作的是不在
263	// 该清册中的无关档案——不返回正常历史、清册或部分报告，不产生业务变更，
264	// 原保存内容保持原样。
265	func TestManifestSnapshotMismatchAfterOpenFailsAllOperations(t *testing.T) {
266		dir := t.TempDir()
267		s, err := Open(dir)
268		if err != nil {
269			t.Fatal(err)
270		}
271		defer s.Close()
272		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
273		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-06-30")
274		// A-1 成功延长到 2025-06-30 后于该日销毁，清册合法保存 2025-06-30。
275		if _, err := s.Revise(ReviseInput{
276			RevisionID: "R-1", ArchiveID: "A-1",
277			OriginalEnd: MustParseDate("2025-01-10"), NewEnd: MustParseDate("2025-06-30"),
278			RevisedOn: MustParseDate("2025-01-09"), Reason: "延期",
279		}); err != nil {
280			t.Fatal(err)
281		}
282		if _, err := s.Destroy(DestructionRequest{
283			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-1"},
284		}); err != nil {
285			t.Fatal(err)
286		}
287		if m, found, err := s.GetManifest("APP-1"); err != nil || !found ||
288			!m.Entries[0].End.Equal(MustParseDate("2025-06-30")) {
289			t.Fatalf("损坏前清册应保存最终期限 2025-06-30: found=%v err=%v %+v", found, err, m)
290		}
291	
292		// 把清册条目里的截止日改回最初登记的 2025-01-10：
293		// 修订链衔接完整、清册归属正确，但两处截止日互相矛盾。
294		rewriteState(t, dir, func(doc map[string]any) {
295			entries := doc["manifests"].(map[string]any)["APP-1"].(map[string]any)["entries"].([]any)
296			entries[0].(map[string]any)["end"] = "2025-01-10"
297		})
298		corruptContent := readStateFile(t, dir)
299	
300		// 重新打开必须失败，错误指出清册申请编号、档案编号与不一致的保管截止日。
301		s2, err := Open(dir)
302		if err == nil {
303			s2.Close()
304			t.Fatal("清册保存最初登记截止日而非最终生效截止日时，打开必须失败")
305		}
306		if !errors.Is(err, ErrCorruptState) ||
307			!strings.Contains(err.Error(), "APP-1") ||
308			!strings.Contains(err.Error(), "A-1") ||
309			!strings.Contains(err.Error(), "保管截止日") {
310			t.Fatalf("打开错误应为 ErrCorruptState 并指出 APP-1/A-1/保管截止日，得到 %v", err)
311		}
312	
313		// 已打开实例上的后续操作全部按整库损坏失败，包括与该清册无关的 A-2。
314		if h, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
315			t.Fatalf("损坏后查询无关档案也必须返回 ErrCorruptState 且无结论: found=%v err=%v", found, err)
316		}
317		if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
318			t.Fatalf("损坏后 History 必须失败且不得给出矛盾历史: found=%v err=%v", found, err)
319		}
320		if m, found, err := s.GetManifest("APP-1"); !errors.Is(err, ErrCorruptState) || found || m.ApplicationID != "" {
321			t.Fatalf("损坏后 GetManifest 必须失败: found=%v err=%v %+v", found, err, m)
322		}
323		if r, err := s.Check(CheckRequest{
324			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
325		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
326			t.Fatalf("损坏后 Check 必须失败且不得给出部分报告: %+v err=%v", r, err)
327		}
328		if m, err := s.Destroy(DestructionRequest{
329			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
330		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
331			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
332		}
333		if err := s.Register(RegisterInput{
334			ID: "A-3", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-06-30"),
335		}); !errors.Is(err, ErrCorruptState) {
336			t.Fatalf("损坏后 Register 必须失败: %v", err)
337		}
338		if _, err := s.Revise(ReviseInput{
339			RevisionID: "R-9", ArchiveID: "A-2",
340			OriginalEnd: MustParseDate("2025-06-30"), NewEnd: MustParseDate("2026-06-30"),
341			RevisedOn: MustParseDate("2025-06-01"), Reason: "延期",
342		}); !errors.Is(err, ErrCorruptState) {
343			t.Fatalf("损坏后 Revise 必须失败: %v", err)
344		}
345		if err := s.Freeze(FreezeInput{
346			ArchiveID: "A-2", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-06-01"),
347		}); !errors.Is(err, ErrCorruptState) {
348			t.Fatalf("损坏后 Freeze 必须失败: %v", err)
349		}
350	
351		// 失败不得触发修复或重新保存：矛盾的清册条目原样保留。
352		if got := readStateFile(t, dir); got != corruptContent {
353			t.Fatalf("失败后原保存内容被改动:\n%q", got)
354		}
355	}
356	
357	// 一份清册收录多份档案时，其中一份条目与档案矛盾即意味着整库读取失败：
358	// 即使另一份条目完全一致，也不能返回它的正常历史、清册或核对结果。
359	func TestOneBadManifestEntryFailsReadsOfOtherEntries(t *testing.T) {
360		dir := t.TempDir()
361		s, err := Open(dir)
362		if err != nil {
363			t.Fatal(err)
364		}
365		defer s.Close()
366		reg(t, s, "A-1", "合同", "2020-01-01", "2025-06-30")
367		reg(t, s, "A-3", "凭证", "2020-01-01", "2025-06-30")
368		if _, err := s.Destroy(DestructionRequest{
369			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-1", "A-3"},
370		}); err != nil {
371			t.Fatal(err)
372		}
373	
374		// 只把 A-1 的类别改坏，A-3 的条目保持一致。
375		rewriteState(t, dir, func(doc map[string]any) {
376			entries := doc["manifests"].(map[string]any)["APP-2"].(map[string]any)["entries"].([]any)
377			for _, e := range entries {
378				if e.(map[string]any)["id"] == "A-1" {
379					e.(map[string]any)["category"] = "凭证"
380				}
381			}
382		})
383		corruptContent := readStateFile(t, dir)
384	
385		s2, err := Open(dir)
386		if err == nil {
387			s2.Close()
388			t.Fatal("一份清册中任一条目矛盾时，打开必须失败")
389		}
390		if !errors.Is(err, ErrCorruptState) ||
391			!strings.Contains(err.Error(), "APP-2") ||
392			!strings.Contains(err.Error(), "A-1") ||
393			!strings.Contains(err.Error(), "类别") {
394			t.Fatalf("打开错误应为 ErrCorruptState 并指出 APP-2/A-1/类别，得到 %v", err)
395		}
396	
397		// 已打开实例：条目完好的 A-3 同样读不到正常结果。
398		if h, found, err := s.History("A-3"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
399			t.Fatalf("同册另一份条目完好也不得返回正常历史: found=%v err=%v", found, err)
400		}
401		if m, found, err := s.GetManifest("APP-2"); !errors.Is(err, ErrCorruptState) || found || m.ApplicationID != "" {
402			t.Fatalf("同册任一条目矛盾时整份清册都不可取回: found=%v err=%v %+v", found, err, m)
403		}
404		if r, err := s.Check(CheckRequest{
405			ApplicationID: "APP-8", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-3"},
406		}); !errors.Is(err, ErrCorruptState) || r.Status != "" {
407			t.Fatalf("核对条目完好的另一份档案也必须整次失败: %+v err=%v", r, err)
408		}
409		if got := readStateFile(t, dir); got != corruptContent {
410			t.Fatalf("失败后原保存内容被改动:\n%q", got)
411		}
412	}
