		"处理日期早于截止日一天": {
			`{"version":1,"archives":{"A-1":` + archive("A-1", "2025-01-10", "") +
				`},"manifests":{` + manifest("APP-1", "2025-01-09", entry("A-1", "2025-01-10")) + `}}`,
			[]string{"APP-1", "A-1", "2025-01-09", "2025-01-10"},
		},
		"多档案清册中第二份未到期": {
