				`,"A-2":` + archive("A-2", "2025-07-01", "") +
				`},"manifests":{` + manifest("APP-1", "2025-06-30",
				entry("A-1", "2025-06-30")+`,`+entry("A-2", "2025-07-01")) + `}}`,
			[]string{"APP-1", "A-2", "2025-06-30", "2025-07-01"},
		},
